<?php
require_owner();
try{$finance=finance_view_data($_GET);}catch(InvalidArgumentException $e){echo '<p role="alert">'.e($e->getMessage()).'</p>';$finance=finance_view_data([]);}
$fd=$finance['dates'];$ft=$finance['totals'];$fp=$finance['previous'];
$query=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';
$filtered=array_values(array_filter($finance['rows'],static fn($r)=>$query===''||mb_stripos($r['description'].' '.$r['category'].' '.$r['type'].' '.(['income'=>'pemasukan','cogs'=>'HPP','expense'=>'pengeluaran'][$r['type']]??'').' '.$r['record_date'],$query)!==false));
$pageSize=10;$totalPages=max(1,(int)ceil(count($filtered)/$pageSize));$recordPage=max(1,min($totalPages,(int)($_GET['record_page']??1)));$pageRows=array_slice($filtered,($recordPage-1)*$pageSize,$pageSize);
$base=['page'=>'admin','tab'=>'reports','period'=>$fd['mode'],'date'=>$fd['date'],'start'=>$fd['start'],'end'=>$fd['last']];
$link=static fn($extra)=>'?'.http_build_query(array_replace($base,$extra));
$money=static fn($n)=>$n===null?'HPP belum lengkap':rupiah($n);
$metrics=[['Total Pendapatan','revenue',false],['Total HPP','cogs',false],['Laba Kotor','gross',false],['Total Biaya Operasional','expense',false],['Laba Bersih','net',false],['Margin Laba','margin',true]];
$chart=finance_chart_data($finance['rows'],$fd);
$costProducts=finance_query('SELECT id,name,cost_price FROM products ORDER BY name')->fetchAll();
$missingItems=finance_query("SELECT i.id,i.product_name,o.order_code FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.cost_at_purchase IS NULL AND o.status IN ('Dikirim','Selesai') AND COALESCE(o.finance_recognized_at,DATE(o.created_at))>=? AND COALESCE(o.finance_recognized_at,DATE(o.created_at))<? ORDER BY o.id,i.id",[$fd['start'],$fd['end']])->fetchAll();
?>
