<section class="erp-card finance-toolbar"><div class="erp-card-head"><div><h2>Laporan Laba Rugi</h2><p><?= e(date('d M Y',strtotime($fd['start']))) ?> – <?= e(date('d M Y',strtotime($fd['last']))) ?></p></div><div class="finance-export"><a class="erp-btn" href="<?= e($link(['export'=>'pdf'])) ?>">Unduh PDF</a><a class="erp-btn" href="<?= e($link(['export'=>'csv'])) ?>">Excel / CSV</a></div></div>
<form method="get" class="finance-filters"><input type="hidden" name="page" value="admin"><input type="hidden" name="tab" value="reports"><label>Periode<select name="period" id="finance-period"><?php foreach(['daily'=>'Harian','weekly'=>'Mingguan','monthly'=>'Bulanan','yearly'=>'Tahunan','custom'=>'Rentang kustom'] as $value=>$label): ?><option value="<?= $value ?>" <?= $fd['mode']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label data-finance-anchor>Tanggal acuan<input type="date" name="date" value="<?= e($fd['date']) ?>" required></label><label data-finance-custom>Dari<input type="date" name="start" value="<?= e($fd['start']) ?>"></label><label data-finance-custom>Sampai<input type="date" name="end" value="<?= e($fd['last']) ?>"></label><button class="erp-btn">Terapkan</button></form>
