<?php if($finance['demo']): ?><p class="finance-notice" role="status"><strong>Data contoh.</strong> Belum ada catatan keuangan toko. Angka, grafik, dan transaksi berikut hanya ilustrasi; tidak disimpan ke database. Ekspor juga ditandai sebagai data contoh.</p><?php endif; ?>
<?php if($ft['missing']): ?><p class="finance-notice" role="alert"><strong>HPP belum lengkap:</strong> <?= (int)$ft['missing'] ?> catatan belum memiliki modal. Lengkapi modal transaksi di bawah agar laba dan margin dapat dihitung.</p><?php endif; ?>
<div class="finance-metrics"><?php foreach($metrics as [$label,$key,$percent]): $value=$key==='cogs'&&$ft['missing']?null:$ft[$key];$prev=$key==='cogs'&&$fp['missing']?null:$fp[$key]; ?>
<article class="erp-card finance-metric"><span><?= $label ?></span><strong class="<?= in_array($key,['net','gross'],true)&&$value!==null?($value<0?'finance-loss':'finance-profit'):'' ?>"><?= $percent?($value===null?'—':number_format($value,2,',','.').'%'):$money($value) ?></strong><small><?= $finance['demo']?'Ilustrasi tampilan':e($percent&&!$ft['missing']&&($value===null||$prev===null)?($value===null?'Belum ada pendapatan':'Belum ada pembanding margin'):finance_change($value===null?null:(float)$value,$prev===null?null:(float)$prev)) ?></small></article>
<?php endforeach; ?></div>
