<nav class="finance-pagination" aria-label="Halaman transaksi"><?php if($recordPage>1): ?><a href="<?= e($link(['q'=>$query,'record_page'=>$recordPage-1])) ?>">← Sebelumnya</a><?php endif; ?><span>Halaman <?= $recordPage ?> dari <?= $totalPages ?></span><?php if($recordPage<$totalPages): ?><a href="<?= e($link(['q'=>$query,'record_page'=>$recordPage+1])) ?>">Berikutnya →</a><?php endif; ?></nav></section>
